import { AbstractSocialCue } from './SocialCue.js';
export class EyeRollingCue extends AbstractSocialCue {
    constructor(animationManager, settings) {
        super(animationManager, settings);
        this.rollInterval = null;
    }

    start() {
        let angle = 0;
        this.rollInterval = setInterval(() => {
            const xMovement = Math.cos(angle) * 40;
            const yMovement = Math.sin(angle) * 40;

            if (xMovement >= 0) {
                this.animationManager.scheduleChange("61", 0, 0, 0);
                this.animationManager.scheduleChange("62", xMovement, 0, 0);
            } else {
                this.animationManager.scheduleChange("62", 0, 0, 0);
                this.animationManager.scheduleChange("61", -xMovement, 0, 0);
            }

            if (yMovement >= 0) {
                this.animationManager.scheduleChange("63", 0, 0, 0);
                this.animationManager.scheduleChange("64", yMovement, 0, 0);
            } else {
                this.animationManager.scheduleChange("64", 0, 0, 0);
                this.animationManager.scheduleChange("63", -yMovement, 0, 0);
            }

            angle += 0.1;
            if (angle >= Math.PI * 2) angle = 0;
        }, 50);
    }

    stop() {
        clearInterval(this.rollInterval);
        this.animationManager.scheduleChange("61", 0, 0, 0);
        this.animationManager.scheduleChange("62", 0, 0, 0);
        this.animationManager.scheduleChange("63", 0, 0, 0);
        this.animationManager.scheduleChange("64", 0, 0, 0);
    }
}
